@@ -581,6 +581,7 @@ VOID ixheaace_initialize_sbr_defaults(ixheaace_pstr_sbr_cfg pstr_config) {
   pstr_config->sbr_pvc_active = 0;
   pstr_config->sbr_harmonic = 0;
